html:
{%- set prog = frappe.get_doc("Programme", doc.programme) -%}
{%- set granted = json.loads(doc.purposes_granted or "[]") -%}
{%- set labels = {"field_worker": _("Tell any field worker"), "slip": _("Tear off and hand in the slip below"),
  "sms": _("SMS STOP to the programme number"), "missed_call": _("Give a missed call to the programme number"),
  "ivr": _("Call the helpline"), "whatsapp": _("Reply STOP on WhatsApp"), "web": _("Use the preference centre"),
  "email": _("Write to the DPO"), "community": _("Tell the SHG, panchayat or camp desk"), "api": _("Through a partner"),
  "ussd": _("USSD menu")} -%}
<style>
  .an-receipt { font-family: Hind, "Noto Sans Devanagari", sans-serif; max-width: 380px; margin: auto; color: #2A2118; }
  .an-receipt .code { font-family: "IBM Plex Mono", monospace; font-size: 30px; letter-spacing: .08em; margin: 6px 0; }
  .an-receipt .slip { border-top: 2px dashed #B4532A; margin-top: 16px; padding-top: 10px; }
  .an-receipt .box { display: inline-block; width: 14px; height: 14px; border: 1.5px solid #2A2118; margin-right: 6px; }
</style>
<div class="an-receipt">
  <div class="small">{{ _("Consent receipt") }} · {{ prog.programme_name }}</div>
  <div class="code">{{ doc.short_code }}</div>
  <div class="small">{{ doc.get_formatted("server_time") }}</div>
  <p><b>{{ _("You agreed to") }}</b></p>
  <ul>
  {%- for code in granted %}
    <li>{{ frappe.db.get_value("Purpose", doc.programme ~ "-" ~ code, "purpose_title") or code }}</li>
  {%- else %}
    <li>{{ _("Nothing: you said no") }}</li>
  {%- endfor %}
  </ul>
  <p><b>{{ _("To stop at any time") }}</b></p>
  <ul>
  {%- for row in prog.withdrawal_channels if row.show_on_receipt %}
    <li>{{ labels.get(row.channel, row.channel) }}</li>
  {%- endfor %}
  </ul>
  <p class="small">{{ _("Keep this code. You can ask what we hold about you, correct it, or complain at any time.") }}</p>
  <div class="slip">
    <b>{{ _("Withdrawal slip") }}</b> · {{ doc.short_code }}
    <p><span class="box"></span>{{ _("Stop everything optional") }}</p>
    <p><span class="box"></span>{{ _("Stop only") }}: ______________________</p>
    <p>{{ _("Thumb or signature") }}: ______________ &nbsp; {{ _("Date") }}: ________</p>
  </div>
</div>
